import { api } from './api.js';
import * as events from './events.js';
import { el, flag, fmtDate, ago, toast } from './ui.js';

// Admin page: create accounts and see every account. A new account's
// password is generated by the server and shown here once; it cannot be
// looked up again afterwards.
export function renderAdmin(host) {
  const email = el('input', { class: 'input', type: 'email', name: 'email', placeholder: 'Email', required: true, autocomplete: 'off' });
  const nickname = el('input', { class: 'input', name: 'nickname', placeholder: 'Nickname', required: true, minlength: '2', maxlength: '32', autocomplete: 'off' });
  const country = el('input', { class: 'input', name: 'country', placeholder: 'Country, e.g. UA (optional)', maxlength: '2', autocomplete: 'off' });
  const submit = el('button', { class: 'btn primary', type: 'submit', text: 'Create user' });
  const created = el('div');
  const countLabel = el('span', { class: 'muted' });
  const tableBody = el('tbody');

  const form = el('form', { class: 'admin-form' }, [email, nickname, country, submit]);
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    submit.disabled = true;
    try {
      const { user, password } = await api.adminCreateUser({
        email: email.value,
        nickname: nickname.value,
        country: country.value,
      });
      form.reset();
      showPassword(user, password);
      await loadUsers();
    } catch (err) {
      toast(err.message, 'error');
    } finally {
      submit.disabled = false;
    }
  });

  function showPassword(user, password) {
    const copy = el('button', {
      class: 'btn small',
      type: 'button',
      text: 'Copy',
      onclick: async () => {
        try {
          await navigator.clipboard.writeText(password);
          copy.textContent = 'Copied';
        } catch (_) {
          toast('Copy failed - select the password and copy it by hand', 'error');
        }
      },
    });
    created.replaceChildren(
      el('div', { class: 'password-once', role: 'status' }, [
        el('div', { class: 'password-once-head' }, [
          el('strong', { text: `Account created for ${user.nickname}` }),
          el('button', { class: 'icon-btn', type: 'button', text: '✕', title: 'Dismiss', 'aria-label': 'Dismiss', onclick: () => created.replaceChildren() }),
        ]),
        el('p', { class: 'muted', text: `Give ${user.email} this password. It is shown only once and cannot be looked up later.` }),
        el('div', { class: 'password-once-row' }, [el('code', { class: 'password-value', text: password }), copy]),
      ])
    );
  }

  function userRow(u) {
    return el('tr', {}, [
      el('td', {}, [
        el('span', { class: 'admin-user' }, [
          el('span', { class: 'chip-avatar', text: u.avatar }),
          el('span', { text: u.nickname }),
          u.isAdmin ? el('span', { class: 'ac-tag', text: 'admin' }) : null,
        ]),
      ]),
      el('td', { text: u.email }),
      el('td', { text: u.country ? `${flag(u.country)} ${u.country}` : '—' }),
      el('td', {}, [el('span', { class: `dot${u.online ? ' online' : ''}`, title: u.online ? 'online' : 'offline' })]),
      el('td', { class: 'muted', text: fmtDate(u.joinedAt) }),
      el('td', { class: 'muted', text: u.online ? 'now' : ago(u.lastSeenAt) }),
    ]);
  }

  async function loadUsers() {
    try {
      const { users } = await api.adminUsers();
      countLabel.textContent = `${users.length} account${users.length === 1 ? '' : 's'}`;
      tableBody.replaceChildren(...users.map(userRow));
    } catch (err) {
      tableBody.replaceChildren(el('tr', {}, [el('td', { colspan: '6', class: 'empty', text: err.message })]));
    }
  }

  host.replaceChildren(
    el('div', { class: 'admin' }, [
      el('section', { class: 'panel' }, [
        el('div', { class: 'panel-head' }, [el('h2', { text: 'New user' })]),
        el('p', { class: 'muted', text: 'A password is generated for the account and shown once, right here.' }),
        form,
        created,
      ]),
      el('section', { class: 'panel' }, [
        el('div', { class: 'panel-head' }, [el('h2', { text: 'Users' }), countLabel]),
        el('div', { class: 'table-wrap' }, [
          el('table', { class: 'admin-table' }, [
            el('thead', {}, [
              el('tr', {}, ['Player', 'Email', 'Country', 'Online', 'Joined', 'Last seen'].map((h) => el('th', { text: h }))),
            ]),
            tableBody,
          ]),
        ]),
      ]),
    ])
  );

  loadUsers();
  email.focus();
  const offPresence = events.on('presence', () => loadUsers());
  return () => offPresence();
}
